// Ekip tanıtımının saf mantığı: sayaç, iletişim satırları, kopyalama ve ekranda maskeli telefon. Sayılar ABACUS'tandır.
import { mask, text } from "@snn/abacus-core";
import { countText } from "../lib/shop-format";

/** Sıra sayacı: "2 / 5". */
const counterText = (index: number, count: number): string => `${countText(index + 1)} / ${countText(count)}`;

export type ShowcaseLayout = "gallery" | "filmstrip" | "directory" | "spotlight";
export const LAYOUTS: { value: ShowcaseLayout; label: string }[] = [
  { value: "gallery", label: "Galeri" },
  { value: "filmstrip", label: "Film şeridi" },
  { value: "directory", label: "Dizin" },
  { value: "spotlight", label: "Ön plan" },
];

export interface TeamMember {
  id: string;
  name: string;
  title: string;
  city?: string;
  country?: string;
  bio?: string;
  /** İletişim bilgisi kişi başına isteğe bağlıdır; herkese açık sayfada bilgi kasıtlı verilir. */
  email?: string;
  phone?: string;
  /** Verilirse gerçek portre; yoksa baş harfli yer tutucu. */
  portrait?: string;
  /** Portrenin odak noktası (CSS object-position), örneğin "50% 30%". */
  portraitPosition?: string;
  tone?: number;
}

export interface ContactRow { kind: "email" | "phone"; value: string; shown: string; label: string }

/** Profilde gösterilecek iletişim satırları: olmayan gizlenir. `maskPhone` ile ekranda telefon maskelenir, kopyalanan değer gerçeğidir. */
export function contactRows(member: TeamMember, maskPhone = false): ContactRow[] {
  const rows: ContactRow[] = [];
  if (member.email) rows.push({ kind: "email", value: member.email, shown: member.email, label: `${member.name} e-postasını kopyala` });
  if (member.phone) rows.push({ kind: "phone", value: member.phone, shown: maskPhone ? mask.phone(member.phone) : member.phone, label: `${member.name} telefonunu kopyala` });
  return rows;
}

export const placeText = (member: Pick<TeamMember, "city" | "country">): string => [member.city, member.country].filter(Boolean).join(", ");
export const counterLine = (index: number, count: number, name: string): string => `${counterText(index, count)} · ${name}`;
export const profileLive = (member: TeamMember): string => `${member.name}, ${member.title} profili gösteriliyor.`;
export const COPIED = "Kopyalandı";
export const COPY_FAILED = "Kopyalanamadı";

/** Panoya yazar; tarayıcı izin vermezse false döner. */
export async function copyText(value: string): Promise<boolean> {
  try {
    if (typeof navigator === "undefined" || !navigator.clipboard) return false;
    await navigator.clipboard.writeText(value);
    return true;
  } catch { return false; }
}

/** Portre yer tutucusu için baş harfler (en çok iki), Türkçe büyük harf kurallı. */
export const initials = (name: string): string => name.trim().split(/\s+/).slice(0, 2).map(part => text.upper(part[0] ?? "")).join("");

.root { container-type: inline-size; display: grid; gap: var(--space-5); min-width: 0; color: var(--foreground); }
.head { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3); }
.title { margin: 0; margin-right: auto; font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); }
.counter { margin: 0; color: var(--text-secondary); font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.portrait { display: block; width: 100%; border-radius: var(--radius-panel); }
.initials { font-family: var(--font-display); font-size: var(--text-4xl); }
.card .portrait { transition: transform var(--duration-standard) var(--ease-standard), box-shadow var(--duration-standard) var(--ease-standard); }
.card:hover .portrait { transform: translateY(-2px); box-shadow: var(--shadow-raised); }
.card:active .portrait { transform: scale(.98); }
.gallery { display: grid; grid-template-columns: repeat(auto-fill, minmax(9.5rem, 1fr)); gap: var(--space-4); }
.film { display: flex; gap: var(--space-4); padding-bottom: var(--space-2); overflow-x: auto; scroll-snap-type: x mandatory; }
.film .card { flex: 0 0 11rem; scroll-snap-align: center; }
.card { display: grid; gap: 2px; align-content: start; padding: var(--space-2); border: 1px solid transparent; border-radius: calc(var(--radius-panel) + var(--space-2)); background: none; transition: background var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard); color: inherit; font: inherit; font-size: var(--text-sm); text-align: left; cursor: pointer; }
.card b { margin-top: var(--space-2); font-family: var(--font-display); font-size: var(--text-base); font-weight: 500; letter-spacing: var(--tracking-display); }
.card span { color: var(--text-secondary); font-size: var(--text-xs); }
.card:hover { background: var(--surface-muted); }
.card[aria-pressed="true"] { border-color: var(--border-strong); background: var(--surface-muted); box-shadow: var(--shadow-resting); }
.card[aria-pressed="true"] b::after { content: ""; display: inline-block; width: .4rem; height: .4rem; margin-left: var(--space-2); border-radius: 50%; background: var(--accent); vertical-align: middle; }
.card:focus-visible, .rowButton:focus-visible, .dot:focus-visible, .copy:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
.detail { min-height: 9rem; padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); }
.profile { display: grid; gap: var(--space-2); }
.profile p { margin: 0; }
.name { margin: 0; font-family: var(--font-display); font-size: var(--text-2xl); font-weight: 500; letter-spacing: var(--tracking-display); }
.role { color: var(--text-secondary); font-size: var(--text-sm); }
.bio { max-width: 40rem; font-size: var(--text-base); }
.contacts { display: flex; flex-wrap: wrap; gap: var(--space-2); margin: var(--space-2) 0 0; padding: 0; list-style: none; }
.copy { transition: background var(--duration-fast) var(--ease-standard), transform var(--duration-fast) var(--ease-standard); display: inline-flex; align-items: center; gap: var(--space-3); min-height: 2.25rem; padding: 0 var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font: inherit; font-size: var(--text-sm); cursor: pointer; }
.copy:hover { background: var(--surface-muted); }
.copy:active { transform: scale(.97); }
.copy i { color: var(--text-muted); font-style: normal; font-size: var(--text-xs); }
.copy i[data-state="copied"] { color: var(--success); }
.copy i[data-state="failed"] { color: var(--danger); }
.directory { display: grid; margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--border); }
.row { border-bottom: 1px solid var(--border); }
.rowButton { display: flex; width: 100%; align-items: baseline; justify-content: space-between; gap: var(--space-3); padding: var(--space-3) 0; border: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }
.rowButton span { color: var(--text-secondary); font-size: var(--text-sm); }
.rowPanel { overflow: hidden; }
.rowInner { display: grid; grid-template-columns: 6rem minmax(0, 1fr); gap: var(--space-4); padding: 0 0 var(--space-4); }
.spotlight { display: grid; gap: var(--space-4); }
.spotBody { display: grid; grid-template-columns: minmax(0, 18rem) minmax(0, 1fr); gap: var(--space-8); align-items: center; }
.picker { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.dot { display: grid; place-items: center; width: 2.5rem; height: 2.5rem; border: 1px solid var(--border); border-radius: 50%; background: var(--surface); color: var(--text-secondary); font: inherit; font-size: var(--text-xs); cursor: pointer; }
.dot[aria-pressed="true"] { border-color: var(--foreground); background: var(--foreground); color: var(--background); }
.rowButton b { font-family: var(--font-display); font-size: var(--text-lg); font-weight: 500; letter-spacing: var(--tracking-display); }
.rowButton:hover b { color: var(--accent-strong); }
@media (prefers-reduced-motion: reduce) { .card, .card .portrait, .copy { transition: none; } .card:hover .portrait { transform: none; } }
.root[data-reduced] .card, .root[data-reduced] .card .portrait, .root[data-reduced] .copy { transition: none; }
@container (max-width: 760px) { .spotBody { gap: var(--space-5); } .detail { padding: var(--space-4); } }
@container (max-width: 440px) { .spotBody { grid-template-columns: minmax(0, 1fr); } .bigPortrait { max-width: 12rem; } .gallery { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; } .gallery .card { flex: 0 0 9rem; scroll-snap-align: center; } .rowInner { grid-template-columns: minmax(0, 1fr); } .smallPortrait { max-width: 6rem; } }

"use client";

import { useEffect, useId, useRef, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import SegmentedControl from "../segmented-control/segmented-control";
import { motionTokens } from "../lib/motion-tokens";
import { FramedPhoto, useAnnouncer } from "../lib/shop-parts";
import { useReducedMotionSafe } from "../lib/viz-utils";
import { COPIED, COPY_FAILED, LAYOUTS, contactRows, copyText, counterLine, initials, placeText, profileLive, type ShowcaseLayout, type TeamMember } from "./team-showcase-format";
import styles from "./team-showcase.module.css";

export type { ShowcaseLayout, TeamMember };

/** Ekibi portre ağırlıklı tanıtan "hakkımızda" bölümü için kullanın: galeri, film şeridi, dizin ya da ön plan yerleşimiyle. Bir kişiye basınca profili yerinde açılır: unvan, şehir, kısa tanım ve kopyalanabilir iletişim bilgileri. İç aranabilir kişi listesi için `team-directory`, üye ve rol yönetimi için `team-members`, müşteri alıntıları için `testimonial-stage`. Gerçek sitede yalnız izin alınmış portre ve bilgi kullanılmalıdır (uygulamanın sorumluluğu). */
export interface TeamShowcaseProps {
  title: string;
  members: TeamMember[];
  /** Başlangıç yerleşimi (varsayılan galeri). Üretimde sabit bir yerleşim seçilir. */
  layout?: ShowcaseLayout;
  /** Yerleşim seçicisini gösterir; yalnız tanıtım ortamı içindir. */
  layoutSwitcher?: boolean;
  /** Telefonu ekranda maskeler (kopyalanan değer gerçektir). */
  maskPhone?: boolean;
  /** Kişi seçilince çağrılır (profil sayfasına gitmek ya da istatistik için). */
  onSelect?: (member: TeamMember, index: number) => void;
}

function Portrait({ member, className }: { member: TeamMember; className?: string }) {
  const label = `${member.name}, ${member.title}`;
  return <FramedPhoto src={member.portrait} position={member.portraitPosition ?? "50% 25%"} alt={label} ratio="4 / 5" tone={member.tone} initial={initials(member.name)} className={[styles.portrait, className].filter(Boolean).join(" ")} />;
}

function CopyButton({ label, value, shown, announce }: { label: string; value: string; shown: string; announce: (message: string) => void }) {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle");
  const timer = useRef<number>(undefined);
  useEffect(() => () => window.clearTimeout(timer.current), []);
  return <button type="button" className={styles.copy} aria-label={label} onClick={async () => {
    const ok = await copyText(value);
    setState(ok ? "copied" : "failed"); announce(ok ? COPIED : COPY_FAILED);
    window.clearTimeout(timer.current); timer.current = window.setTimeout(() => setState("idle"), 1800);
  }}><span>{shown}</span><i data-state={state} aria-hidden="true">{state === "copied" ? COPIED : state === "failed" ? COPY_FAILED : "Kopyala"}</i></button>;
}

function Profile({ member, maskPhone, announce, heading = true }: { member: TeamMember; maskPhone: boolean; announce: (message: string) => void; heading?: boolean }) {
  const rows = contactRows(member, maskPhone);
  const place = placeText(member);
  return <div className={styles.profile}>
    {heading ? <h3 className={styles.name}>{member.name}</h3> : <p className={styles.name}>{member.name}</p>}
    <p className={styles.role}>{member.title}{place && <> · {place}</>}</p>
    {member.bio && <p className={styles.bio}>{member.bio}</p>}
    {rows.length > 0 && <ul className={styles.contacts}>{rows.map(row => <li key={row.kind}><CopyButton label={row.label} value={row.value} shown={row.shown} announce={announce} /></li>)}</ul>}
  </div>;
}

export function TeamShowcase({ title, members, layout: initial = "gallery", layoutSwitcher = false, maskPhone = false, onSelect }: TeamShowcaseProps) {
  const reduced = useReducedMotionSafe();
  const uid = useId();
  const [layout, setLayout] = useState<ShowcaseLayout>(initial);
  const [index, setIndex] = useState(0);
  const [live, announce] = useAnnouncer();
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const member = members[Math.min(index, members.length - 1)];
  if (!member) return null;

  const pick = (at: number) => {
    setIndex(at); onSelect?.(members[at]!, at); announce(profileLive(members[at]!));
    if (!reduced) buttons.current[at]?.scrollIntoView?.({ behavior: "smooth", inline: "center", block: "nearest" });
  };
  const fade = reduced ? { duration: 0 } : { duration: motionTokens.duration.standard };
  const card = (item: TeamMember, at: number) => <button key={item.id} ref={node => { buttons.current[at] = node; }} type="button" className={styles.card} aria-pressed={at === index} onClick={() => pick(at)}>
    <Portrait member={item} /><b>{item.name}</b><span>{item.title}</span>
  </button>;
  const profile = <AnimatePresence mode="wait" initial={false}><motion.div key={member.id} initial={reduced ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={fade}><Profile member={member} maskPhone={maskPhone} announce={announce} /></motion.div></AnimatePresence>;

  return <section className={styles.root} aria-labelledby={`${uid}-title`} data-layout={layout} data-reduced={reduced || undefined}>
    <header className={styles.head}>
      <h2 id={`${uid}-title`} className={styles.title}>{title}</h2>
      <p className={styles.counter} aria-hidden="true">{counterLine(index, members.length, member.name)}</p>
      {layoutSwitcher && <SegmentedControl label="Yerleşim" options={LAYOUTS} value={layout} onValueChange={value => setLayout(value as ShowcaseLayout)} />}
    </header>
    {layout === "gallery" && <><div className={styles.gallery}>{members.map(card)}</div><div className={styles.detail}>{profile}</div></>}
    {layout === "filmstrip" && <><div className={styles.film}>{members.map(card)}</div><div className={styles.detail}>{profile}</div></>}
    {layout === "directory" && <ul className={styles.directory}>{members.map((item, at) => {
      const open = at === index;
      return <li key={item.id} className={styles.row} data-open={open || undefined}>
        <button ref={node => { buttons.current[at] = node; }} type="button" className={styles.rowButton} aria-expanded={open} aria-controls={`${uid}-row-${item.id}`} onClick={() => pick(at)}><b>{item.name}</b><span>{item.title}</span></button>
        <AnimatePresence initial={false}>{open && <motion.div key="panel" id={`${uid}-row-${item.id}`} role="region" aria-label={item.name} className={styles.rowPanel} initial={reduced ? false : { height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={reduced ? { duration: 0 } : motionTokens.spring.smooth}>
          <div className={styles.rowInner}><Portrait member={item} className={styles.smallPortrait} /><Profile member={item} maskPhone={maskPhone} announce={announce} heading={false} /></div>
        </motion.div>}</AnimatePresence>
      </li>;
    })}</ul>}
    {layout === "spotlight" && <div className={styles.spotlight}>
      <AnimatePresence mode="wait" initial={false}><motion.div key={member.id} className={styles.spotBody} initial={reduced ? false : { opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0 }} transition={fade}><Portrait member={member} className={styles.bigPortrait} /><Profile member={member} maskPhone={maskPhone} announce={announce} /></motion.div></AnimatePresence>
      <div className={styles.picker} role="group" aria-label="Kişiler">{members.map((item, at) => <button key={item.id} ref={node => { buttons.current[at] = node; }} type="button" className={styles.dot} aria-pressed={at === index} aria-label={`${item.name}, ${item.title}`} onClick={() => pick(at)}>{initials(item.name)}</button>)}</div>
    </div>}
    {live}
  </section>;
}

export default TeamShowcase;
